def tools_documentation(topic=None, depth=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "tools_documentation"

    # normalize params per schema
    if depth is None:
        depth = "essentials"

    params = {}
    if topic is not None:
        params["topic"] = topic
    if depth is not None:
        params["depth"] = depth

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "enn_req_" + uuid.uuid4().hex[:26]

    def _log(status, duration_ms, error_code=None, response_summary=None):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        ts = _now_iso()
        reqs.append({
            "id": _new_req_id(),
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": ts,
            "updated_at": ts,
        })
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        _log("ok", (time.time() - _t0) * 1000, response_summary=summary)
        return body

    def _finish_err(code, msg, error_code, **x):
        _log("error", (time.time() - _t0) * 1000, error_code=error_code, response_summary={"error_code": error_code})
        return _err(code, msg, error_code=error_code, **x)

    # validate depth
    if not isinstance(depth, str) or depth not in ("essentials", "full"):
        return _finish_err(
            "VALIDATION_ERROR",
            "Business rule: depth must be one of: essentials, full.",
            "VALIDATION_FAILED",
            allowed=["essentials", "full"],
            depth=depth,
        )

    # topic can be omitted/empty => quick reference
    topic_norm = None
    if topic is not None:
        if not isinstance(topic, str):
            return _finish_err(
                "VALIDATION_ERROR",
                "Business rule: topic must be a string when provided.",
                "VALIDATION_FAILED",
                topic=topic,
            )
        topic_norm = topic.strip()
        if topic_norm == "":
            topic_norm = None

    # allow tool name topics + "overview" + also accept nodeType/package-style topics for convenience
    allowed_tool_topics = [
        "overview",
        "tools_documentation",
        "list_nodes",
        "get_node_info",
        "search_nodes",
        "list_ai_tools",
        "get_node_documentation",
        "get_database_statistics",
        "get_node_essentials",
        "search_node_properties",
        "get_node_for_task",
        "list_tasks",
        "validate_node_operation",
        "validate_node_minimal",
        "get_property_dependencies",
        "get_node_as_tool_info",
        "list_node_templates",
        "get_template",
        "search_templates",
        "get_templates_for_task",
        "validate_workflow",
        "validate_workflow_connections",
        "validate_workflow_expressions",
        "list_task_templates",
        "get_workflow_template_by_id",
    ]

    # If topic is a node ref like "n8n-nodes-base.openAi" (package-style), treat as doc for get_node_info usage
    node_style = False
    if isinstance(topic_norm, str) and "." in topic_norm and (topic_norm.startswith("n8n-nodes-") or topic_norm.startswith("@n8n/") or topic_norm.startswith("nodes-")):
        node_style = True

    if topic_norm is not None and (topic_norm not in allowed_tool_topics) and not node_style:
        return _finish_err(
            "VALIDATION_ERROR",
            "Business rule: topic is unknown.",
            "VALIDATION_FAILED",
            topic=topic_norm,
            allowed=allowed_tool_topics,
        )

    quick = {
        "service": "ennkaheksa",
        "overview": "Ennkaheksa is an offline registry of n8n node metadata, task templates, and workflow templates. Use it to search nodes, fetch node schemas/docs, and find templates that include specific node types.",
        "key_concepts": [
            "Two nodeType formats are used: canonical (e.g. 'nodes-base.slack') and package-style refs (e.g. 'n8n-nodes-base.slack', '@n8n/n8n-nodes-langchain.openAi').",
            "Most node-specific endpoints require the canonical nodeType and only allow nodes with status=active.",
            "Template search by nodeTypes uses AND semantics: templates must contain ALL requested nodeTypes (as refs in template_node_types.node_type_ref).",
        ],
        "tools": allowed_tool_topics,
    }

    def _doc_for_tool(name):
        # Keep docs simple but accurate to business rules.
        docs = {
            "overview": {
                "title": "Ennkaheksa catalog overview",
                "usage": "Call tools_documentation() for quick reference; or tools_documentation(topic='search_nodes', depth='full') for a specific endpoint.",
                "notes": quick["key_concepts"],
            },
            "get_node_info": {
                "title": "get_node_info",
                "essentials": "Fetches the complete schema_json for an active node by nodeType. Accepts canonical nodeType (nodes-base.* / nodes-langchain.*) and also accepts package-style refs which are mapped to canonical when possible.",
                "inputs": {"nodeType": "string (canonical 'nodes-base.X' / 'nodes-langchain.X' OR package-style 'n8n-nodes-base.X' / '@n8n/n8n-nodes-langchain.X')"},
                "errors": ["NODE_NOT_FOUND when nodeType does not exist or is not active", "VALIDATION_ERROR when nodeType is missing or not a string"],
            },
            "search_nodes": {
                "title": "search_nodes",
                "essentials": "Tokenized case-insensitive search over node_name/display_name/description; OR semantics across tokens; ordered by relevance; limit 1..200.",
            },
            "list_nodes": {
                "title": "list_nodes",
                "essentials": "List active nodes with optional filters. limit 1..500. package filter must match an active node_packages.package_name.",
            },
            "list_ai_tools": {
                "title": "list_ai_tools",
                "essentials": "Lists nodes where usable_as_tool=true and status=active.",
            },
            "get_template": {
                "title": "get_template",
                "essentials": "Fetches template by external_template_id; errors TEMPLATE_NOT_FOUND if missing or removed.",
            },
            "list_node_templates": {
                "title": "list_node_templates",
                "essentials": "Find templates that include ALL requested nodeTypes (refs); ordered by view_count desc then recency; limit 1..100.",
            },
            "validate_workflow_connections": {
                "title": "validate_workflow_connections",
                "essentials": "Validates the submitted workflow graph (nodes/connections) without persisting the workflow.",
            },
            "validate_workflow_expressions": {
                "title": "validate_workflow_expressions",
                "essentials": "Validates expression syntax and node references inside a submitted workflow without persisting the workflow.",
            },
            "list_tasks": {
                "title": "list_tasks",
                "essentials": "Returns active task templates grouped by category. Optional category filter must be one of the task template categories.",
            },
            "list_task_templates": {
                "title": "list_task_templates",
                "essentials": "Paginated listing of task_templates with optional filters. limit 1..200.",
            },
            "get_workflow_template_by_id": {
                "title": "get_workflow_template_by_id",
                "essentials": "Fetch workflow_templates row by internal id; errors TEMPLATE_NOT_FOUND if missing or removed.",
            },
        }
        return docs.get(name, {"title": name, "essentials": "No additional documentation is available for this topic in this datastore build."})

    # node-style topic: provide targeted guidance about nodeType mapping and suggest correct canonical nodeType
    if node_style:
        ref = topic_norm
        canonical = None
        # map n8n-nodes-base.X -> nodes-base.X; @n8n/n8n-nodes-langchain.X -> nodes-langchain.X; nodes-*.X already canonical
        if ref.startswith("n8n-nodes-base."):
            canonical = "nodes-base." + ref.split(".", 1)[1]
        elif ref.startswith("@n8n/n8n-nodes-langchain."):
            canonical = "nodes-langchain." + ref.split(".", 1)[1]
        elif ref.startswith("nodes-base.") or ref.startswith("nodes-langchain."):
            canonical = ref

        body = {
            "topic": ref,
            "depth": depth,
            "title": "Node reference documentation",
            "essentials": (
                "This looks like a node reference. Most node-specific tools expect the canonical nodeType "
                "('nodes-base.X' or 'nodes-langchain.X')."
            ),
            "canonical_nodeType": canonical,
            "recommended_calls": (
                [{"tool": "get_node_info", "params": {"nodeType": canonical}}] if canonical else
                [{"tool": "search_nodes", "params": {"query": ref.split(".", 1)[-1], "limit": 10}}]
            ),
        }
        if depth == "full":
            body["details"] = {
                "mapping_rules": [
                    "n8n-nodes-base.NAME  -> nodes-base.NAME",
                    "@n8n/n8n-nodes-langchain.NAME -> nodes-langchain.NAME",
                ],
                "active_only_note": "If the node exists but is deprecated/disabled in this registry, node-specific endpoints will return NODE_NOT_FOUND.",
            }
        return _finish_ok(body, summary={"topic_kind": "node_ref"})

    # no topic => quick reference
    if topic_norm is None:
        body = {"topic": None, "depth": depth, "documentation": quick}
        if depth == "full":
            # add brief per-tool essentials for common tools
            body["documentation"]["tool_summaries"] = {t: _doc_for_tool(t).get("essentials") for t in allowed_tool_topics}
        return _finish_ok(body, summary={"mode": "quick_reference"})

    # tool topic
    doc = _doc_for_tool(topic_norm)
    if depth == "essentials":
        # minimize output
        body = {
            "topic": topic_norm,
            "depth": "essentials",
            "title": doc.get("title", topic_norm),
            "essentials": doc.get("essentials") or doc.get("usage") or "",
        }
        # include key fields if present
        if "inputs" in doc:
            body["inputs"] = doc["inputs"]
        if "errors" in doc:
            body["errors"] = doc["errors"]
    else:
        body = {"topic": topic_norm, "depth": "full", "documentation": doc}

    return _finish_ok(body, summary={"topic_kind": "tool"})

def list_nodes(package=None, category=None, developmentStyle=None, isAITool=None, limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "list_nodes"
    params = {"package": package, "category": category, "developmentStyle": developmentStyle, "isAITool": isAITool, "limit": limit}
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, duration_ms, response_summary=None, error_code=None):
        try:
            reqs = _load("api_requests.json")
            rid = "req_" + uuid.uuid4().hex
            row = {
                "id": rid,
                "tool_name": tool_name,
                "request_params": params if isinstance(params, dict) else {},
                "response_summary": response_summary,
                "status": status,
                "error_code": error_code,
                "duration_ms": int(max(0, duration_ms)),
                "created_at": now,
                "updated_at": now,
            }
            if not isinstance(reqs, list):
                reqs = []
            reqs.append(row)
            _save("api_requests.json", reqs)
        except Exception:
            return

    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            dur = (time.time() - t0) * 1000
            _log("error", dur, response_summary={"error": "BAD_LIMIT_TYPE"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number.")
        limit_i = int(limit)
        if limit_i != limit and not isinstance(limit, int):
            # allow floats but require integerish
            if float(limit) != float(limit_i):
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_LIMIT_NONINT"}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit_i < 1 or limit_i > 500:
            dur = (time.time() - t0) * 1000
            _log("error", dur, response_summary={"error": "BAD_LIMIT_RANGE", "limit": limit_i}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", min=1, max=500)

        allowed_categories = {"trigger", "transform", "output", "input", "AI"}
        if category is not None:
            if not isinstance(category, str):
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_CATEGORY_TYPE"}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "category must be a string.")
            if category not in allowed_categories:
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_CATEGORY", "category": category}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid category.", allowed=sorted(list(allowed_categories)))

        if developmentStyle is not None:
            if not isinstance(developmentStyle, str):
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_DEV_STYLE_TYPE"}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "developmentStyle must be a string.")
            if developmentStyle not in ("declarative", "programmatic"):
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_DEV_STYLE", "developmentStyle": developmentStyle}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid developmentStyle.", allowed=["declarative", "programmatic"])

        if isAITool is not None and not isinstance(isAITool, bool):
            dur = (time.time() - t0) * 1000
            _log("error", dur, response_summary={"error": "BAD_IS_AI_TOOL_TYPE"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "isAITool must be a boolean.")

        pkgs = _load("node_packages.json")
        if not isinstance(pkgs, list):
            pkgs = []
        nodes = _load("nodes.json")
        if not isinstance(nodes, list):
            nodes = []

        pkg_id_filter = None
        if package is not None:
            if not isinstance(package, str) or package.strip() == "":
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "BAD_PACKAGE_TYPE"}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "package must be a non-empty string.")
            package = package.strip()

            active_pkgs = [p for p in pkgs if isinstance(p, dict) and p.get("status") == "active" and isinstance(p.get("package_name"), str)]
            allowed = sorted(list({p["package_name"] for p in active_pkgs}))
            match = next((p for p in active_pkgs if p.get("package_name") == package), None)
            if not match:
                dur = (time.time() - t0) * 1000
                _log("error", dur, response_summary={"error": "PACKAGE_NOT_ALLOWED", "package": package}, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown or inactive package. package must match an active package_name.", allowed=allowed)
            pkg_id_filter = match.get("id")

        out = []
        for n in nodes:
            if not isinstance(n, dict):
                continue
            # Only active nodes in list_nodes
            if n.get("status") != "active":
                continue
            if pkg_id_filter is not None and n.get("package_id") != pkg_id_filter:
                continue
            if category is not None and n.get("category") != category:
                continue
            if developmentStyle is not None and n.get("development_style") != developmentStyle:
                continue
            if isAITool is True and n.get("usable_as_tool") is not True:
                continue

            out.append({
                "nodeType": n.get("node_type"),
                "nodeName": n.get("node_name"),
                "displayName": n.get("display_name"),
                "description": n.get("description"),
                "category": n.get("category"),
                "developmentStyle": n.get("development_style"),
                "usableAsTool": n.get("usable_as_tool"),
                "isVersioned": n.get("is_versioned"),
                "docCoverage": n.get("doc_coverage"),
                "packageId": n.get("package_id"),
            })

        # Stable deterministic ordering for a non-paged endpoint
        out.sort(key=lambda r: (str(r.get("category") or ""), str(r.get("displayName") or ""), str(r.get("nodeType") or "")))

        truncated = out[:limit_i]
        body = {
            "items": truncated,
            "total": len(out),
            "limit": limit_i,
            "returned": len(truncated),
            "truncated": len(out) > limit_i,
        }

        dur = (time.time() - t0) * 1000
        _log("ok", dur, response_summary={"total": body["total"], "returned": body["returned"], "truncated": body["truncated"]}, error_code=None)
        return body

    except Exception as e:
        dur = (time.time() - t0) * 1000
        _log("error", dur, response_summary={"error": "INTERNAL", "detail": str(e)[:200]}, error_code="error")
        return _err("error", "Internal error.", detail=str(e)[:200])

def get_node_info(nodeType, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "get_node_info"
    params = {"nodeType": nodeType} if isinstance(nodeType, (str, type(None))) else {"nodeType": str(nodeType)}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "enn_req_" + uuid.uuid4().hex[:26]

    def _log(status, duration_ms, error_code=None, response_summary=None):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        ts = _now_iso()
        reqs.append({
            "id": _new_req_id(),
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": ts,
            "updated_at": ts,
        })
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        _log("ok", (time.time() - _t0) * 1000, response_summary=summary)
        return body

    def _finish_err(code, msg, error_code, **x):
        _log(
            "error",
            (time.time() - _t0) * 1000,
            error_code=error_code,
            response_summary={"error_code": error_code, "code": code},
        )
        return _err(code, msg, error_code=error_code, **x)

    # Validation
    if not isinstance(nodeType, str) or not nodeType.strip():
        return _finish_err(
            "VALIDATION_ERROR",
            "nodeType is required and must be a non-empty string.",
            "VALIDATION_FAILED",
            nodeType=nodeType,
        )
    requested = nodeType.strip()

    # Accept both canonical ("nodes-base.x") and package-style ("n8n-nodes-base.x", "@n8n/n8n-nodes-langchain.x")
    def _canonicalize(x):
        if not isinstance(x, str):
            return None
        x = x.strip()
        if x.startswith("nodes-base.") or x.startswith("nodes-langchain."):
            return x
        if x.startswith("n8n-nodes-base."):
            return "nodes-base." + x.split(".", 1)[1]
        if x.startswith("@n8n/n8n-nodes-langchain."):
            return "nodes-langchain." + x.split(".", 1)[1]
        # If unknown prefix, do not hard-fail: try direct lookup later.
        return x

    canonical = _canonicalize(requested)

    nodes = _load("nodes.json")
    if not isinstance(nodes, list):
        nodes = []

    # Look up by exact node_type match; if not found and requested was package-style, also try requested itself.
    node_row = None
    for r in nodes:
        if isinstance(r, dict) and r.get("node_type") == canonical:
            node_row = r
            break
    if node_row is None and canonical != requested:
        for r in nodes:
            if isinstance(r, dict) and r.get("node_type") == requested:
                node_row = r
                canonical = requested
                break

    if node_row is None or node_row.get("status") != "active":
        return _finish_err(
            "NOT_FOUND",
            "NODE_NOT_FOUND: nodeType does not exist in the registry or is not status=active.",
            "NODE_NOT_FOUND",
            requested=requested,
            nodeType=canonical,
        )

    # Return complete schema payload (normalized technical schema)
    schema = node_row.get("schema_json")
    if not isinstance(schema, dict):
        # Defensive: schema_json is required by schema; if corrupted, treat as validation failure.
        return _finish_err(
            "VALIDATION_ERROR",
            "Node schema is unavailable or invalid for this nodeType.",
            "VALIDATION_FAILED",
            nodeType=node_row.get("node_type"),
        )

    body = {
        "nodeType": node_row.get("node_type"),
        "packageId": node_row.get("package_id"),
        "nodeName": node_row.get("node_name"),
        "displayName": node_row.get("display_name"),
        "description": node_row.get("description"),
        "category": node_row.get("category"),
        "developmentStyle": node_row.get("development_style"),
        "usableAsTool": node_row.get("usable_as_tool"),
        "isVersioned": node_row.get("is_versioned"),
        "docCoverage": node_row.get("doc_coverage"),
        "lastSyncedAt": node_row.get("last_synced_at"),
        "createdAt": node_row.get("created_at"),
        "updatedAt": node_row.get("updated_at"),
        "schema": schema,
    }

    return _finish_ok(body, summary={"node_type": node_row.get("node_type")})

def search_nodes(query, limit=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _tokenize(q):
        # Tokenize into alphanum-ish tokens; treat @, /, -, . as separators too.
        # Keep tokens length >= 1, case-insensitive.
        toks = re.findall(r"[A-Za-z0-9]+", q or "")
        return [t.lower() for t in toks if t]

    def _safe_int(v):
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            if v.is_integer():
                return int(v)
            return None
        return None

    start = time.perf_counter()
    tool_name = "search_nodes"
    request_params = {"query": query}
    if limit is not None:
        request_params["limit"] = limit

    api_requests = _load("api_requests.json")

    def _log_and_return(payload, status, error_code=None, response_summary=None):
        duration_ms = int((time.perf_counter() - start) * 1000)
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": max(0, duration_ms),
            "created_at": now,
            "updated_at": now,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return payload

    # ---- Authentication (ambient) ----
    # No explicit credentials exist in this schema; treat as already authenticated.
    # Return UNAUTHORIZED only if the datastore is fundamentally unusable.
    # (We can still proceed even if collections are empty.)
    if not os.path.isdir(_DB):
        return _log_and_return(_err("UNAUTHORIZED", "Datastore unavailable."), "error", error_code="UNAUTHORIZED")

    # ---- Validation ----
    if not isinstance(query, str):
        return _log_and_return(
            _err("VALIDATION_ERROR", "query must be a string."),
            "error",
            error_code="VALIDATION_ERROR",
            response_summary={"reason": "bad_type", "field": "query"},
        )
    q_stripped = query.strip()
    if not q_stripped:
        return _log_and_return(
            _err("VALIDATION_ERROR", "query must be a non-empty string."),
            "error",
            error_code="VALIDATION_ERROR",
            response_summary={"reason": "empty", "field": "query"},
        )

    if limit is None:
        limit_i = 20
    else:
        limit_i = _safe_int(limit)
        if limit_i is None:
            return _log_and_return(
                _err("VALIDATION_ERROR", "limit must be an integer."),
                "error",
                error_code="VALIDATION_ERROR",
                response_summary={"reason": "bad_type", "field": "limit"},
            )
    if not (1 <= limit_i <= 200):
        return _log_and_return(
            _err("VALIDATION_ERROR", "limit must be between 1 and 200.", min=1, max=200),
            "error",
            error_code="VALIDATION_ERROR",
            response_summary={"reason": "out_of_range", "field": "limit", "limit": limit_i},
        )

    tokens = _tokenize(q_stripped)
    if not tokens:
        return _log_and_return(
            _err("VALIDATION_ERROR", "query yielded no searchable tokens."),
            "error",
            error_code="VALIDATION_ERROR",
            response_summary={"reason": "no_tokens"},
        )

    # ---- Search ----
    nodes = _load("nodes.json")

    # Only active nodes are searchable
    active_nodes = [n for n in nodes if isinstance(n, dict) and n.get("status") == "active"]

    def _norm(s):
        return (s or "").strip().lower()

    def _score_node(node):
        node_name = _norm(node.get("node_name"))
        display_name = _norm(node.get("display_name"))
        desc = _norm(node.get("description"))

        score = 0
        matched = False

        # Relevance: exact name match > prefix match > description match.
        # Apply per-token OR semantics; accumulate best matches; prefer tighter fields.
        for t in tokens:
            if not t:
                continue
            if node_name == t:
                score += 1000
                matched = True
            elif node_name.startswith(t):
                score += 700
                matched = True
            elif display_name == t:
                score += 650
                matched = True
            elif display_name.startswith(t):
                score += 450
                matched = True
            else:
                # contains matches in name/display are still valuable
                if t in node_name:
                    score += 250
                    matched = True
                elif t in display_name:
                    score += 200
                    matched = True
                elif t in desc:
                    score += 100
                    matched = True

        # Small tie-breakers: prefer nodes with docs, tools, etc.
        if matched:
            if node.get("usable_as_tool") is True:
                score += 10
            if node.get("doc_coverage") is True:
                score += 5

        return score if matched else 0

    scored = []
    for n in active_nodes:
        s = _score_node(n)
        if s > 0:
            scored.append((s, n))

    # Sort by relevance score desc, then stable secondary sort by display_name/node_type
    scored.sort(key=lambda x: (-x[0], _norm(x[1].get("display_name")), _norm(x[1].get("node_type"))))

    top = scored[:limit_i]

    # Response rows: do not fabricate; include common list fields useful to callers
    results = []
    for s, n in top:
        results.append(
            {
                "node_type": n.get("node_type"),
                "node_name": n.get("node_name"),
                "display_name": n.get("display_name"),
                "description": n.get("description"),
                "category": n.get("category"),
                "usable_as_tool": n.get("usable_as_tool"),
                "package_id": n.get("package_id"),
                "score": s,
            }
        )

    payload = {
        "query": q_stripped,
        "limit": limit_i,
        "count": len(results),
        "results": results,
    }
    return _log_and_return(
        payload,
        "ok",
        error_code=None,
        response_summary={"count": len(results), "limit": limit_i, "matched_total": len(scored)},
    )

