        _log("ok", dur, response_summary=summary, error_code=None)
        return body

    def _finish_err(code, msg, error_code):
        dur = (time.time() - _t0) * 1000.0
        _log("error", dur, response_summary={"error_code": error_code}, error_code=error_code)
        return _err(code, msg, error_code=error_code)

    # Validate
    if limit is None:
        limit = 50
    if not isinstance(limit, (int, float)) or isinstance(limit, bool):
        return _finish_err("VALIDATION_ERROR", "limit must be a number between 1 and 500.", "BAD_LIMIT")
    if int(limit) != limit:
        # allow floats that are integral
        if not (isinstance(limit, float) and limit.is_integer()):
            return _finish_err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.", "BAD_LIMIT")
    limit = int(limit)
    if limit < 1 or limit > 500:
        return _finish_err("VALIDATION_ERROR", "limit must be between 1 and 500.", "BAD_LIMIT")

    if package is not None and not isinstance(package, str):
        return _finish_err("VALIDATION_ERROR", "package must be a string.", "VALIDATION_FAILED")
    if category is not None:
        if not isinstance(category, str):
            return _finish_err("VALIDATION_ERROR", "category must be a string.", "VALIDATION_FAILED")
        if category not in {"trigger", "transform", "output", "input", "AI"}:
            return _finish_err("VALIDATION_ERROR", "Invalid category. Allowed: trigger, transform, output, input, AI.", "VALIDATION_FAILED")
    if developmentStyle is not None:
        if not isinstance(developmentStyle, str):
            return _finish_err("VALIDATION_ERROR", "developmentStyle must be a string.", "VALIDATION_FAILED")
        if developmentStyle not in {"declarative", "programmatic"}:
            return _finish_err("VALIDATION_ERROR", "Invalid developmentStyle. Allowed: declarative, programmatic.", "VALIDATION_FAILED")

    # Resolve package filter must match an ACTIVE package_name when provided
    pkg_id = None
    if package is not None:
        pkgs = _load("node_packages.json")
        active_pkgs = [p for p in pkgs if p.get("status") == "active"]
        match = next((p for p in active_pkgs if p.get("package_name") == package), None)
        if not match:
            allowed = sorted({p.get("package_name") for p in active_pkgs if isinstance(p.get("package_name"), str)})
            return _finish_err(
                "VALIDATION_ERROR",
                "package must match an active package_name.",
                "VALIDATION_FAILED",
            ) if False else _finish_err(
                "VALIDATION_ERROR",
                "package must match an active package_name. Allowed values are the active packages.",
                "VALIDATION_FAILED"
            )
        pkg_id = match.get("id")

    # No explicit auth parameter exists; per contract this must not reject. No rate-limit schema provided; skip enforcement.

    nodes = _load("nodes.json")
    pkgs = _load("node_packages.json")
    pkg_by_id = {p.get("id"): p for p in pkgs if isinstance(p, dict)}

    # Filter: usable_as_tool=true AND status=active
    res = []
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("status") != "active":
            continue
        if n.get("usable_as_tool") is not True:
            continue

        # Only return nodes whose owning package is active (consistent with package filtering rule)
        p = pkg_by_id.get(n.get("package_id"))
        if not p or p.get("status") != "active":
            continue

        if pkg_id is not None and n.get("package_id") != pkg_id:
            continue
        if category is not None and n.get("category") != category:
            continue
        if developmentStyle is not None and n.get("development_style") != developmentStyle:
            continue

        res.append(n)

    # stable ordering: display_name then node_type
    res.sort(key=lambda x: ((x.get("display_name") or ""), (x.get("node_type") or "")))
    if len(res) > limit:
        res = res[:limit]

    # Response shape: return node types and small metadata useful to callers
    out_items = []
    for n in res:
        p = pkg_by_id.get(n.get("package_id"), {})
        out_items.append({
            "nodeType": n.get("node_type"),
            "nodeName": n.get("node_name"),
            "displayName": n.get("display_name"),
            "description": n.get("description"),
            "category": n.get("category"),
            "developmentStyle": n.get("development_style"),
            "package": p.get("package_name"),
            "packageDisplayName": p.get("display_name"),
        })

    return _finish_ok(
        {
            "items": out_items,
            "count": len(out_items),
            "limit": limit,
            "filters": {k: v for k, v in {"package": package, "category": category, "developmentStyle": developmentStyle}.items() if v is not None},
        },
        summary={"count": len(out_items), "limit": limit}
    )

