    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "get_database_statistics"
    params = {}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, duration_ms, response_summary=None, error_code=None):
        reqs = _load("api_requests.json")
        now = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool_name": tool_name,
            "request_params": params,
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        dur = (time.time() - _t0) * 1000.0
        _log("ok", dur, response_summary=summary, error_code=None)
        return body

    def _finish_err(code, msg, error_code):
        dur = (time.time() - _t0) * 1000.0
        _log("error", dur, response_summary={"error_code": error_code}, error_code=error_code)
        return _err(code, msg, error_code=error_code)

    # Validate: no parameters allowed
    if _extra:
        return _finish_err("VALIDATION_ERROR", "This endpoint does not take parameters.", "VALIDATION_FAILED")

    nodes = _load("nodes.json")
    pkgs = _load("node_packages.json")

    active_pkgs = [p for p in pkgs if isinstance(p, dict) and p.get("status") == "active"]
    active_pkg_ids = {p.get("id") for p in active_pkgs if isinstance(p.get("id"), str)}
    pkg_by_id = {p.get("id"): p for p in pkgs if isinstance(p, dict) and isinstance(p.get("id"), str)}

    active_nodes = []
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("status") != "active":
            continue
        if n.get("package_id") not in active_pkg_ids:
            continue
        active_nodes.append(n)

    total_active_nodes = len(active_nodes)
    usable_as_tool = sum(1 for n in active_nodes if n.get("usable_as_tool") is True)
    versioned = sum(1 for n in active_nodes if n.get("is_versioned") is True)
    doc_covered = sum(1 for n in active_nodes if n.get("doc_coverage") is True)

    by_category = {}
    for c in ["trigger", "transform", "output", "input", "AI"]:
        by_category[c] = 0
    for n in active_nodes:
        c = n.get("category")
        if c in by_category:
            by_category[c] += 1

    # by package (active packages only)
    by_package = {}
    for n in active_nodes:
        pid = n.get("package_id")
        p = pkg_by_id.get(pid, {})
        pname = p.get("package_name") or pid or "unknown"
        if pname not in by_package:
            by_package[pname] = {"active_nodes": 0, "usable_as_tool": 0}
        by_package[pname]["active_nodes"] += 1
        if n.get("usable_as_tool") is True:
            by_package[pname]["usable_as_tool"] += 1

    doc_pct = 0.0
    if total_active_nodes > 0:
        doc_pct = (doc_covered / total_active_nodes) * 100.0

    # also include package registry totals
    pkg_totals = {
        "active": sum(1 for p in pkgs if isinstance(p, dict) and p.get("status") == "active"),
        "deprecated": sum(1 for p in pkgs if isinstance(p, dict) and p.get("status") == "deprecated"),
        "disabled": sum(1 for p in pkgs if isinstance(p, dict) and p.get("status") == "disabled"),
        "total": sum(1 for p in pkgs if isinstance(p, dict)),
    }

    body = {
        "nodes": {
            "total_active": total_active_nodes,
            "usable_as_tool_active": usable_as_tool,
            "versioned_active": versioned,
            "doc_coverage_active_count": doc_covered,
            "doc_coverage_active_percentage": doc_pct,
            "by_category_active": by_category,
        },
        "packages": {
            "totals": pkg_totals,
            "by_package_active": by_package,
        },
    }

    return _finish_ok(body, summary={"total_active_nodes": total_active_nodes, "usable_as_tool": usable_as_tool})

