    if not isinstance(query, str) or not query.strip():
        _log("error", summary={"reason": "bad_query"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if maxResults is None:
        maxResults_i = 20
    else:
        if not (isinstance(maxResults, int) or (isinstance(maxResults, float) and maxResults.is_integer())):
            _log("error", summary={"reason": "bad_maxResults_type"}, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 200")
        maxResults_i = int(maxResults)
    if maxResults_i < 1 or maxResults_i > 200:
        _log("error", summary={"reason": "bad_maxResults_range", "maxResults": maxResults_i}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "maxResults must be between 1 and 200")

    nodes = _load("nodes.json")
    node = None
    for r in nodes:
        if r.get("node_type") == nodeType:
            node = r
            break

    if not node or node.get("status") != "active":
        _log("error", summary={"nodeType": nodeType}, error_code="NODE_NOT_FOUND")
        return _err("NOT_FOUND", "Node type not found or not active", error_code="NODE_NOT_FOUND", nodeType=nodeType)

    prop_index = node.get("property_index")
    if not isinstance(prop_index, list):
        prop_index = []

    q = query.strip().lower()
    # Tokenize: words and dotted paths, keep short tokens too
    tokens = [t for t in re.split(r"[\s/,_\-]+", q) if t]
    if not tokens:
        tokens = [q]

    def _norm(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            try:
                s = json.dumps(s, ensure_ascii=False)
            except Exception:
                s = str(s)
        return s.lower()

    results = []
    for entry in prop_index:
        if not isinstance(entry, dict):
            continue
        path = entry.get("path")
        name = entry.get("name")
        typ = entry.get("type")
        desc = entry.get("description")
        required = entry.get("required")
        dos = entry.get("displayOptionsSummary")

        path_n = _norm(path)
        name_n = _norm(name)
        desc_n = _norm(desc)

        # OR semantics across tokens (match if any token hits)
        best = 0
        matched = False
        matched_tokens = 0
        for tok in tokens:
            if not tok:
                continue
            tok_n = tok.lower()
            hit = 0
            # Relevance: exact path/name > contains path/name > description contains
            if tok_n == path_n or tok_n == name_n:
                hit = 300
            elif path_n and (path_n.startswith(tok_n) or name_n.startswith(tok_n)):
                hit = 220
            elif (tok_n in path_n) or (tok_n in name_n):
                hit = 180
            elif tok_n in desc_n:
                hit = 120
            if hit > 0:
                matched = True
                matched_tokens += 1
                best = max(best, hit)

        if not matched:
            continue

        # Slight boost for matching more tokens
        score = best + min(50, matched_tokens * 10)

        results.append(
            {
                "path": path,
                "name": name,
                "type": typ,
                "description": desc,
                "required": bool(required) if isinstance(required, bool) else required,
                "displayOptionsSummary": dos,
                "_score": score,
            }
        )

    results.sort(key=lambda x: (x.get("_score", 0), _norm(x.get("path")), _norm(x.get("name"))), reverse=True)
    trimmed = []
    for r in results[:maxResults_i]:
        r2 = dict(r)
        r2.pop("_score", None)
        trimmed.append(r2)

    resp = {
        "nodeType": nodeType,
        "query": query,
        "maxResults": maxResults_i,
        "count": len(trimmed),
        "results": trimmed,
    }
    _log("ok", summary={"count": len(trimmed)})
    return resp

