def list_tasks(category=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "list_tasks"
    params = {}
    if category is not None:
        params["category"] = category

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "enn_req_" + uuid.uuid4().hex[:26]

    def _log(status, duration_ms, error_code=None, response_summary=None):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        ts = _now_iso()
        reqs.append({
            "id": _new_req_id(),
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": ts,
            "updated_at": ts,
        })
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        _log("ok", (time.time() - _t0) * 1000, response_summary=summary)
        return body

    def _finish_err(code, msg, error_code, **x):
        _log(
            "error",
            (time.time() - _t0) * 1000,
            error_code=error_code,
            response_summary={"error_code": error_code, "code": code},
        )
        return _err(code, msg, error_code=error_code, **x)

    allowed = ["HTTP/API", "Webhooks", "Database", "AI/LangChain", "Data Processing", "Communication"]

    cat = None
    if category is not None:
        # Relaxed behavior per audit: if a non-supported category is provided,
        # treat it as "no filter" instead of rejecting (older clients sometimes send node categories).
        if not isinstance(category, str) or not category.strip():
            return _finish_err(
                "VALIDATION_ERROR",
                "category must be a non-empty string when provided.",
                "VALIDATION_FAILED",
                allowed_categories=allowed,
                category=category,
            )
        cat = category.strip()
        if cat not in allowed:
            cat = None  # ignore unknown category filter

    tasks = _load("task_templates.json")
    if not isinstance(tasks, list):
        tasks = []

    rows = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("status") != "active":
            continue
        tcat = t.get("category")
        if cat is not None and tcat != cat:
            continue
        rows.append(t)

    grouped = {}
    for r in rows:
        c = r.get("category")
        if not isinstance(c, str):
            continue
        grouped.setdefault(c, [])
        # "task names" = task_key (identifier used by get_node_for_task)
        tk = r.get("task_key")
        if isinstance(tk, str) and tk not in grouped[c]:
            grouped[c].append(tk)

    # stable ordering
    for c in list(grouped.keys()):
        grouped[c].sort()

    body = {
        "categories": grouped,
        "meta": {
            "total_tasks": sum(len(v) for v in grouped.values()),
            "category_filter_applied": (category is not None and isinstance(category, str) and category.strip() in allowed),
            "allowed_categories": allowed,
        },
    }
    return _finish_ok(body, summary={"total": body["meta"]["total_tasks"], "categories": len(grouped)})

def validate_node_operation(nodeType, config, profile=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, summary=None, error_code=None):
        duration_ms = int(round((time.time() - t0) * 1000))
        reqs = _load("api_requests.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool_name": "validate_node_operation",
            "request_params": {"nodeType": nodeType, "config": config, "profile": profile},
            "response_summary": summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": max(0, duration_ms),
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    allowed_profiles = ["strict", "runtime", "ai-friendly", "minimal"]
    if profile is None:
        profile = "ai-friendly"
    if not isinstance(profile, str) or profile not in allowed_profiles:
        _log("error", summary={"reason": "bad_profile", "profile": profile}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "profile must be one of: strict, runtime, ai-friendly, minimal", allowed=allowed_profiles)

    if not isinstance(nodeType, str) or not nodeType.strip():
        _log("error", summary={"reason": "bad_nodeType"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nodeType must be a non-empty string")
    if not isinstance(config, dict):
        _log("error", summary={"reason": "bad_config_type"}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "config must be an object")

    nodes = _load("nodes.json")
    node = None
    for r in nodes:
        if r.get("node_type") == nodeType:
            node = r
            break
    if not node or node.get("status") != "active":
        _log("error", summary={"nodeType": nodeType}, error_code="NODE_NOT_FOUND")
        return _err("NOT_FOUND", "Node type not found or not active", error_code="NODE_NOT_FOUND", nodeType=nodeType)

    essentials = node.get("essentials_json") if isinstance(node.get("essentials_json"), dict) else {}
    schema = node.get("schema_json") if isinstance(node.get("schema_json"), dict) else {}

    def _get_by_path(obj, path):
        cur = obj
        for p in path:
            if isinstance(cur, dict) and p in cur:
                cur = cur[p]
            else:
                return None, False
        return cur, True

    def _path_split(p):
        # supports "a.b.c" and "a[0].b" (treat indexes as strings)
        parts = []
        for chunk in re.split(r"\.", p):
            if not chunk:
                continue
            m = re.findall(r"([^\[\]]+)|\[(\d+)\]", chunk)
            for a, b in m:
                parts.append(a if a else b)
        return parts

    def _exists_path(cfg, path_str):
        parts = _path_split(path_str)
        _, ok = _get_by_path(cfg, parts)
        return ok

    def _infer_required_from_schema(s):
        # Try to interpret a JSON-schema-like object:
        # {properties:{...}, required:[...]} nested possibly under "properties" or "parameters"/"inputs"
        required = set()

        def walk(obj, base_path=""):
            if not isinstance(obj, dict):
                return
            props = obj.get("properties")
            req = obj.get("required")
            if isinstance(req, list):
                for k in req:
                    if isinstance(k, str) and k:
                        required.add((base_path + "." + k).strip("."))
            if isinstance(props, dict):
                for k, v in props.items():
                    if not isinstance(k, str):
                        continue
                    new_base = (base_path + "." + k).strip(".")
                    if isinstance(v, dict):
                        walk(v, new_base)

        walk(s, "")
        return sorted(required)

    # Determine required fields:
    # Prefer essentials_json.required_user_inputs if present; else essentials_json.required_fields; else infer from schema_json.
    required_paths = []
    req_ui = essentials.get("required_user_inputs")
    if isinstance(req_ui, list):
        for e in req_ui:
            if isinstance(e, dict) and isinstance(e.get("path"), str) and e["path"].strip():
                required_paths.append(e["path"].strip())
    if not required_paths:
        req_fields = essentials.get("required_fields")
        if isinstance(req_fields, list):
            required_paths = [p.strip() for p in req_fields if isinstance(p, str) and p.strip()]
    if not required_paths:
        required_paths = _infer_required_from_schema(schema)

    errors = []
    warnings = []
    suggestions = []
    examples = []

    def add_error(code, message, path=None, fix=None):
        e = {"code": code, "message": message}
        if path is not None:
            e["path"] = path
        if fix is not None:
            e["fix"] = fix
        errors.append(e)

    # Required fields check (all profiles)
    missing = []
    for p in required_paths:
        if not _exists_path(config, p):
            missing.append(p)
    for p in missing:
        add_error(
            "MISSING_REQUIRED_FIELD",
            f"Missing required field: {p}",
            path=p,
            fix=f"Add `{p}` to the node config.",
        )

    # Minimal stops here
    if profile == "minimal":
        resp = {
            "nodeType": nodeType,
            "profile": profile,
            "valid": len(errors) == 0,
            "errors": errors,
            "warnings": [],
            "suggestions": [],
            "examples": [],
        }
        _log("ok", summary={"valid": resp["valid"], "errors": len(errors), "warnings": 0})
        return resp

    # Runtime: critical type/format checks (best-effort based on property_index types)
    prop_index = node.get("property_index") if isinstance(node.get("property_index"), list) else []
    type_by_path = {}
    for e in prop_index:
        if isinstance(e, dict) and isinstance(e.get("path"), str):
            type_by_path[e["path"]] = e.get("type")

    def _type_ok(expected, value):
        if expected is None:
            return True
        if not isinstance(expected, str):
            return True
        exp = expected.lower()
        if exp in ("string", "str", "text"):
            return isinstance(value, str)
        if exp in ("number", "float", "decimal"):
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if exp in ("integer", "int"):
            return isinstance(value, int) and not isinstance(value, bool)
        if exp in ("boolean", "bool"):
            return isinstance(value, bool)
        if exp in ("object", "json", "dict"):
            return isinstance(value, dict)
        if exp in ("array", "list"):
            return isinstance(value, list)
        return True

    # Validate required paths' types if we know them
    for p in required_paths:
        parts = _path_split(p)
        val, ok = _get_by_path(config, parts)
        if not ok:
            continue
        expected = type_by_path.get(p)
        if expected and not _type_ok(expected, val):
            add_error(
                "INVALID_TYPE",
                f"Invalid type for {p}: expected {expected}",
                path=p,
                fix=f"Set `{p}` to a value of type {expected}.",
            )

    # runtime also checks obvious empty strings for required fields
    for p in required_paths:
        parts = _path_split(p)
        val, ok = _get_by_path(config, parts)
        if not ok:
            continue
        if isinstance(val, str) and not val.strip():
            add_error(
                "EMPTY_REQUIRED_FIELD",
                f"Required field {p} must not be empty",
                path=p,
                fix=f"Provide a non-empty value for `{p}`.",
            )

    # ai-friendly / strict: add best-practice warnings (heuristics)
    if profile in ("ai-friendly", "strict"):
        # Warn if credentials-like keys are missing when config indicates auth
        # Heuristic: if any value contains "oauth" or "token" but no credentials object/id field exists
        cfg_dump = ""
        try:
            cfg_dump = json.dumps(config, ensure_ascii=False).lower()
        except Exception:
            cfg_dump = str(config).lower()

        has_credentials = False
        # common shapes: credentials, authentication, auth, token
        for k in ("credentials", "credential", "authentication", "auth"):
            if isinstance(config.get(k), (dict, str)) and config.get(k):
                has_credentials = True
                break

        if (("oauth" in cfg_dump) or ("token" in cfg_dump) or ("api key" in cfg_dump) or ("apikey" in cfg_dump)) and not has_credentials:
            warnings.append(
                {
                    "code": "MISSING_CREDENTIALS_HINT",
                    "message": "Config mentions authentication but no credentials/auth section is present.",
                    "fix": "Add a credentials/authentication block appropriate for this node (e.g., credentials.id or auth settings).",
                }
            )

        # Suggest reviewing operation selection if schema seems to be multi-operation
        # Heuristic: presence of property paths containing 'operation' or 'resource'
        has_op = any(isinstance(e, dict) and isinstance(e.get("path"), str) and e["path"].endswith(".operation") for e in prop_index)
        has_res = any(isinstance(e, dict) and isinstance(e.get("path"), str) and e["path"].endswith(".resource") for e in prop_index)
        if (has_op or has_res) and ("operation" not in config and "resource" not in config):
            suggestions.append(
                {
                    "code": "OPERATION_NOT_SET",
                    "message": "This node likely supports multiple operations; operation/resource fields are not set at the top level.",
                    "next_step": "Set `resource` and/or `operation` (or the node-specific operation selector fields).",
                }
            )

        # Provide a minimal example when errors exist
        if errors:
            example_cfg = {}
            for p in required_paths[:10]:
                # populate with placeholders
                example_cfg[p] = "<REQUIRED>"
            examples.append(
                {
                    "title": "Minimal required fields (placeholders)",
                    "example": example_cfg,
                }
            )

        # strict: elevate some warnings if they look critical
        if profile == "strict":
            # if required field exists but is None, make it an error (runtime already checks empty strings)
            for p in required_paths:
                parts = _path_split(p)
                val, ok = _get_by_path(config, parts)
                if ok and val is None:
                    add_error(
                        "NULL_REQUIRED_FIELD",
                        f"Required field {p} must not be null",
                        path=p,
                        fix=f"Set `{p}` to a non-null value.",
                    )

    resp = {
        "nodeType": nodeType,
        "profile": profile,
        "valid": (len(errors) == 0),
        "errors": errors,
        "warnings": warnings,
        "suggestions": suggestions,
        "examples": examples,
    }
    _log("ok", summary={"valid": resp["valid"], "errors": len(errors), "warnings": len(warnings)})
    return resp

def validate_node_minimal(nodeType, config, **_extra):
