        _log("error", {"error_code": "NODE_NOT_FOUND"}, "NODE_NOT_FOUND")
        return out

    essentials = node.get("essentials_json") if isinstance(node.get("essentials_json"), dict) else {}
    schema = node.get("schema_json") if isinstance(node.get("schema_json"), dict) else {}

    # Extract required field paths:
    # Preferred: essentials_json.required_user_inputs (array of {path,...})
    required_paths = []
    rui = essentials.get("required_user_inputs")
    if isinstance(rui, list):
        for it in rui:
            if isinstance(it, dict):
                p = it.get("path")
                if isinstance(p, str) and p.strip():
                    required_paths.append(p.strip())

    # Fallback: schema_json.required_user_inputs (if present)
    if not required_paths:
        rui2 = schema.get("required_user_inputs")
        if isinstance(rui2, list):
            for it in rui2:
                if isinstance(it, dict):
                    p = it.get("path")
                    if isinstance(p, str) and p.strip():
                        required_paths.append(p.strip())

    # Fallback: JSONSchema-like "required" at root + "properties"
    if not required_paths:
        req = schema.get("required")
        if isinstance(req, list):
            for k in req:
                if isinstance(k, str) and k.strip():
                    required_paths.append(k.strip())

    # Deduplicate while preserving order
    seen = set()
    req_paths = []
    for p in required_paths:
        if p not in seen:
            seen.add(p)
            req_paths.append(p)

    def _get_path(obj, path):
        # Supports dot and bracket notation: a.b[0].c
        # If a key contains dots, this won't work; acceptable for this datastore.
        cur = obj
        # tokenize
        tokens = []
        i = 0
        while i < len(path):
            if path[i] == ".":
                i += 1
                continue
            if path[i] == "[":
                j = path.find("]", i + 1)
                if j == -1:
                    return (False, None)
                idx_s = path[i + 1:j].strip()
                if not idx_s.isdigit():
                    return (False, None)
                tokens.append(int(idx_s))
                i = j + 1
                continue
            # key
            j = i
            while j < len(path) and path[j] not in ".[":
                j += 1
            tokens.append(path[i:j])
            i = j

        for tok in tokens:
            if isinstance(tok, int):
                if not isinstance(cur, list) or tok < 0 or tok >= len(cur):
                    return (False, None)
                cur = cur[tok]
            else:
                if not isinstance(cur, dict) or tok not in cur:
                    return (False, None)
                cur = cur[tok]
        return (True, cur)

    missing = []
    ill_typed = []

    # Validate presence and minimal type correctness when type is known from essentials required_user_inputs entries
    type_by_path = {}
    if isinstance(rui, list):
        for it in rui:
            if isinstance(it, dict):
                p = it.get("path")
                ty = it.get("type")
                if isinstance(p, str) and p.strip() and isinstance(ty, str) and ty.strip():
                    type_by_path[p.strip()] = ty.strip().lower()

    def _type_ok(val, tname):
        if tname in ("string", "text"):
            return isinstance(val, str)
        if tname in ("number", "float", "double"):
            return isinstance(val, (int, float)) and not isinstance(val, bool)
        if tname in ("integer", "int"):
            return isinstance(val, int) and not isinstance(val, bool)
        if tname in ("boolean", "bool"):
            return isinstance(val, bool)
        if tname in ("object", "json", "dict"):
            return isinstance(val, dict)
        if tname in ("array", "list"):
            return isinstance(val, list)
        # Unknown: don't type-check in minimal profile
        return True

    for p in req_paths:
        ok, val = _get_path(config, p)
        if not ok or val is None:
            missing.append(p)
            continue
        tname = type_by_path.get(p)
        if tname and not _type_ok(val, tname):
            ill_typed.append({"path": p, "expected": tname})

    if ill_typed:
        out = _err(
            "VALIDATION_ERROR",
            "One or more required fields are present but ill-typed",
            error_code="VALIDATION_FAILED",
            details={"ill_typed": ill_typed, "missing_required": missing},
        )
        _log("error", {"missing_required_count": len(missing), "ill_typed_count": len(ill_typed)}, "VALIDATION_FAILED")
        return out

    resp = {
        "nodeType": nodeType,
        "valid": len(missing) == 0,
        "missing_required": missing,
        "required_field_count": len(req_paths),
    }
    _log("ok", {"valid": resp["valid"], "missing_required_count": len(missing)}, None)
    return resp

def get_property_dependencies(nodeType, config=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
            # type: ignore
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, summary=None, error_code=None):
        api_requests = _load("api_requests.json")
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "tool_name": "get_property_dependencies",
            "request_params": {"nodeType": nodeType, "config": config},
            "response_summary": summary if summary is not None else None,
            "status": status,
            "error_code": error_code,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    if not isinstance(nodeType, str) or not nodeType.strip():
        out = _err("VALIDATION_ERROR", "nodeType must be a non-empty string", error_code="VALIDATION_FAILED")
        _log("error", {"error_code": "VALIDATION_FAILED"}, "VALIDATION_FAILED")
        return out
    if config is not None and not isinstance(config, dict):
        out = _err("VALIDATION_ERROR", "config must be an object when provided", error_code="VALIDATION_FAILED")
        _log("error", {"error_code": "VALIDATION_FAILED"}, "VALIDATION_FAILED")
        return out

    nodes = _load("nodes.json")
    node = next((n for n in nodes if n.get("node_type") == nodeType and n.get("status") == "active"), None)
    if not node:
        out = _err("NOT_FOUND", "Node not found or not active", error_code="NODE_NOT_FOUND")
        _log("error", {"error_code": "NODE_NOT_FOUND"}, "NODE_NOT_FOUND")
        return out

    graph = node.get("dependency_index")
    if not isinstance(graph, list):
        graph = []

    # If no config, return raw graph
    if config is None:
        resp = {"nodeType": nodeType, "dependency_graph": graph}
        _log("ok", {"edges": len(graph)}, None)
        return resp

    def _get_path(obj, path):
        cur = obj
        tokens = []
        i = 0
        while i < len(path):
            if path[i] == ".":
                i += 1
                continue
            if path[i] == "[":
                j = path.find("]", i + 1)
                if j == -1:
                    return (False, None)
                idx_s = path[i + 1:j].strip()
                if not idx_s.isdigit():
                    return (False, None)
                tokens.append(int(idx_s))
                i = j + 1
                continue
            j = i
            while j < len(path) and path[j] not in ".[":
                j += 1
            tokens.append(path[i:j])
            i = j
        for tok in tokens:
            if isinstance(tok, int):
                if not isinstance(cur, list) or tok < 0 or tok >= len(cur):
                    return (False, None)
                cur = cur[tok]
            else:
                if not isinstance(cur, dict) or tok not in cur:
                    return (False, None)
                cur = cur[tok]
        return (True, cur)

    def _truthy(v):
        if isinstance(v, bool):
            return v
        if v is None:
            return False
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return v != 0
        if isinstance(v, str):
            return v.strip().lower() not in ("", "0", "false", "no", "off", "null", "none")
        if isinstance(v, (list, dict)):
            return len(v) > 0
        return True

    def _eval_condition(cond, cfg):
        # Supported shapes:
        # - bool
        # - string: "path" or "path==value" or "path!=value"
        # - dict: {"path": "...", "equals": x} / {"path":"...", "notEquals": x} / {"path":"...", "in":[...]} / {"path":"...", "exists": true}
        if isinstance(cond, bool):
            return cond
        if isinstance(cond, dict):
            p = cond.get("path")
            if not isinstance(p, str) or not p.strip():
                return False
            ok, val = _get_path(cfg, p.strip())
            if "exists" in cond:
                want = bool(cond.get("exists"))
                return ok if want else (not ok)
            if "equals" in cond:
                return ok and val == cond.get("equals")
            if "notEquals" in cond:
                return (not ok) or val != cond.get("notEquals")
            if "in" in cond and isinstance(cond.get("in"), list):
                return ok and val in cond.get("in")
            # Fallback to truthiness
            return ok and _truthy(val)
        if isinstance(cond, str):
            s = cond.strip()
            if not s:
                return False
            # basic operators
            for op in ("==", "!="):
                if op in s:
                    left, right = s.split(op, 1)
                    left = left.strip()
                    right = right.strip()
                    # parse right
                    if (right.startswith('"') and right.endswith('"')) or (right.startswith("'") and right.endswith("'")):
                        rv = right[1:-1]
                    elif right.lower() in ("true", "false"):
                        rv = right.lower() == "true"
                    elif right.lower() in ("null", "none"):
                        rv = None
                    else:
                        try:
                            rv = int(right)
                        except Exception:
                            try:
                                rv = float(right)
                            except Exception:
                                rv = right
                    ok, val = _get_path(cfg, left)
                    if not ok:
                        return op == "!="
                    return (val == rv) if op == "==" else (val != rv)
            ok, val = _get_path(cfg, s)
            return ok and _truthy(val)
        return False

    visible = set()
    hidden = set()
    triggered = 0

    for edge in graph:
        if not isinstance(edge, dict):
            continue
        cond = edge.get("condition")
        if not _eval_condition(cond, config):
            continue
        triggered += 1
        reveals = edge.get("reveals")
        hides = edge.get("hides")
        if isinstance(reveals, list):
            for p in reveals:
                if isinstance(p, str) and p.strip():
                    visible.add(p.strip())
                    hidden.discard(p.strip())
        if isinstance(hides, list):
            for p in hides:
                if isinstance(p, str) and p.strip():
                    hidden.add(p.strip())
                    visible.discard(p.strip())

    resp = {
        "nodeType": nodeType,
        "dependency_graph": graph,
        "visibility": {
            "visible": sorted(visible),
            "hidden": sorted(hidden),
            "triggered_rules": triggered,
        },
    }
    _log("ok", {"edges": len(graph), "triggered_rules": triggered, "visible": len(visible), "hidden": len(hidden)}, None)
    return resp

