def list_node_templates(nodeTypes, limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "list_node_templates"
    params = {"nodeTypes": nodeTypes}
    if limit is not None:
        params["limit"] = limit

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "enn_req_" + uuid.uuid4().hex[:26]

    def _log(status, duration_ms, error_code=None, response_summary=None):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        ts = _now_iso()
        reqs.append({
            "id": _new_req_id(),
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": ts,
            "updated_at": ts,
        })
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        _log("ok", (time.time() - _t0) * 1000, response_summary=summary)
        return body

    def _finish_err(code, msg, error_code, **x):
        _log("error", (time.time() - _t0) * 1000, error_code=error_code, response_summary={"error_code": error_code})
        return _err(code, msg, error_code=error_code, **x)

    if not isinstance(nodeTypes, list) or len(nodeTypes) == 0:
        return _finish_err(
            "VALIDATION_ERROR",
            "Business rule: nodeTypes must be a non-empty array of strings.",
            "VALIDATION_FAILED",
        )
    cleaned = []
    for x in nodeTypes:
        if not isinstance(x, str) or not x.strip():
            return _finish_err(
                "VALIDATION_ERROR",
                "Business rule: nodeTypes must contain only non-empty strings.",
                "VALIDATION_FAILED",
                bad_value=x,
            )
        cleaned.append(x.strip())

    # limit: 1..100 (business rule)
    if limit is None:
        limit_i = 10
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _finish_err("VALIDATION_ERROR", "Business rule: limit must be a number.", "BAD_LIMIT", limit=limit)
        if int(limit) != limit:
            return _finish_err("VALIDATION_ERROR", "Business rule: limit must be an integer.", "BAD_LIMIT", limit=limit)
        limit_i = int(limit)
        if limit_i < 1 or limit_i > 100:
            return _finish_err(
                "VALIDATION_ERROR",
                "Business rule: list_node_templates.limit must be between 1 and 100.",
                "BAD_LIMIT",
                limit=limit_i,
            )

    # MUST treat nodeTypes as AND filter over template_node_types.node_type_ref (business rules)
    tnts = _load("template_node_types.json")
    if not isinstance(tnts, list):
        tnts = []

    templates = _load("workflow_templates.json")
    if not isinstance(templates, list):
        templates = []

    # Determine which requested nodeTypes exist in registry (as refs in template_node_types)
    existing_refs = set()
    for r in tnts:
        if isinstance(r, dict) and isinstance(r.get("node_type_ref"), str):
            existing_refs.add(r["node_type_ref"])

    missing = [nt for nt in cleaned if nt not in existing_refs]
    if len(missing) == len(cleaned):
        # per tool description: NOT_FOUND if none of provided node types exist in registry
        return _finish_err(
            "NOT_FOUND",
            "NODE_NOT_FOUND: none of the provided nodeTypes exist in the registry.",
            "NODE_NOT_FOUND",
            nodeTypes=cleaned,
        )

    # Build template -> set(refs) and counts for those refs
    refs_by_template = {}
    for r in tnts:
        if not isinstance(r, dict):
            continue
        tid = r.get("template_id")
        ref = r.get("node_type_ref")
        if not isinstance(tid, str) or not isinstance(ref, str):
            continue
        refs_by_template.setdefault(tid, set()).add(ref)

    # Filter templates: must include all requested refs (AND)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    matched = []
    for tpl in templates:
        if not isinstance(tpl, dict):
            continue
        if tpl.get("status") != "active":
            continue
        tid = tpl.get("id")
        if not isinstance(tid, str):
            continue
        have = refs_by_template.get(tid, set())
        if all(req in have for req in cleaned):
            matched.append(tpl)

    # Ordering: view_count desc then recency (updated_at/published_at/created_at)
    def _recency_key(tpl):
        for k in ("updated_at", "published_at", "created_at"):
            dt = _parse_dt(tpl.get(k))
            if dt is not None:
                return dt
        return datetime.datetime(1970, 1, 1)

    matched.sort(key=lambda t: (-(t.get("view_count") if isinstance(t.get("view_count"), int) else 0), _recency_key(t)), reverse=False)
    # because second key is datetime; we used negative view_count but reverse=False -> ok, for recency we want newest first, so invert:
    matched.sort(key=lambda t: (-(t.get("view_count") if isinstance(t.get("view_count"), int) else 0), -_recency_key(t).timestamp()))

    out_rows = []
    for tpl in matched[:limit_i]:
        out_rows.append({
            "id": tpl.get("id"),
            "templateId": tpl.get("external_template_id"),
            "name": tpl.get("name"),
            "description": tpl.get("description"),
            "viewCount": tpl.get("view_count"),
            "sourceUrl": tpl.get("source_url"),
            "publishedAt": tpl.get("published_at"),
            "updatedAt": tpl.get("updated_at"),
        })

    body = {
        "templates": out_rows,
        "limit": limit_i,
        "returned": len(out_rows),
        "missingNodeTypes": missing,  # informative; not an error if some missing
        "filterMode": "AND",
    }
    return _finish_ok(body, summary={"returned": len(out_rows), "missing": len(missing)})

