    if limit_int < 1 or limit_int > 200:
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.", error_code="VALIDATION_ERROR")

    q = query.strip().lower()
    tokens = [t for t in re.split(r"\s+", q) if t]
    if not tokens:
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`query` must be a non-empty string.", error_code="VALIDATION_ERROR")

    templates = _load("workflow_templates.json")

    def _text(t):
        name = t.get("name") or ""
        desc = t.get("description") or ""
        return (name, desc, (name + " " + desc).strip())

    scored = []
    for t in templates:
        if t.get("status") != "active":
            continue
        name, desc, both = _text(t)
        name_l = name.lower()
        desc_l = desc.lower()
        both_l = both.lower()

        # Match if any token in name or description
        matched_any = False
        score = 0
        for tok in tokens:
            if tok in name_l or tok in desc_l:
                matched_any = True
                if name_l == tok:
                    score += 1000
                elif name_l.startswith(tok):
                    score += 400
                elif tok in name_l:
                    score += 200
                elif tok in desc_l:
                    score += 80
                else:
                    score += 10
        if matched_any:
            scored.append((score, t))

    # Order: relevance score desc, then view_count desc, then recency (updated_at/published_at) desc
    def _dt_key(s):
        if not s or not isinstance(s, str):
            return ""
        return s

    scored.sort(
        key=lambda x: (
            x[0],
            int(x[1].get("view_count") or 0),
            _dt_key(x[1].get("updated_at")) or _dt_key(x[1].get("published_at")) or "",
        ),
        reverse=True,
    )

    results = []
    for score, t in scored[:limit_int]:
        results.append({
            "templateId": t.get("external_template_id"),
            "name": t.get("name"),
            "description": t.get("description"),
            "viewCount": t.get("view_count"),
            "publishedAt": t.get("published_at"),
            "sourceUrl": t.get("source_url"),
            "taskTag": t.get("task_tag"),
            "updatedAt": t.get("updated_at"),
        })

    resp = {
        "results": results,
        "count": len(results),
        "limit": limit_int,
        "query": query,
    }
    _log("ok", params, {"count": len(results), "limit": limit_int}, None)
    return resp

def validate_workflow(workflow, options=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, params, response_summary=None, error_code=None):
        api_requests = _load("api_requests.json")
        rid = _new_id("req")
        duration_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": rid,
            "tool_name": "validate_workflow",
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    # Defaults
    opt = options if options is not None else {}
    params = {"workflow": workflow, "options": opt}

    # Validation of inputs
    if not isinstance(workflow, dict):
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`workflow` must be an object.", error_code="VALIDATION_ERROR")
    if options is not None and not isinstance(options, dict):
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`options` must be an object when provided.", error_code="VALIDATION_ERROR")

    validateNodes = opt.get("validateNodes", True)
    validateConnections = opt.get("validateConnections", True)
    validateExpressions = opt.get("validateExpressions", True)
    profile = opt.get("profile", "runtime")

    if not isinstance(validateNodes, bool) or not isinstance(validateConnections, bool) or not isinstance(validateExpressions, bool):
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Option flags validateNodes/validateConnections/validateExpressions must be boolean.", error_code="VALIDATION_ERROR")

    if profile not in ("minimal", "runtime", "ai-friendly", "strict"):
        _log("error", params, {"status": "error"}, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`options.profile` must be one of: minimal, runtime, ai-friendly, strict.", error_code="VALIDATION_ERROR")

    report = {
        "ok": True,
        "profile": profile,
        "options": {
            "validateNodes": validateNodes,
            "validateConnections": validateConnections,
            "validateExpressions": validateExpressions,
        },
        "errors": [],
        "warnings": [],
        "suggestions": [],
        "summary": {
            "errorCount": 0,
            "warningCount": 0,
            "suggestionCount": 0,
            "nodeCount": 0,
            "connectionProblems": 0,
            "expressionProblems": 0,
        },
    }

    # Basic workflow structure checks
    nodes = workflow.get("nodes")
    connections = workflow.get("connections")
    if not isinstance(nodes, list):
        report["errors"].append({
            "code": "WORKFLOW_INVALID",
            "message": "Workflow must include `nodes` as an array.",
            "path": "nodes",
        })
    if not isinstance(connections, dict):
        report["errors"].append({
            "code": "WORKFLOW_INVALID",
            "message": "Workflow must include `connections` as an object.",
            "path": "connections",
        })

    if isinstance(nodes, list):
        report["summary"]["nodeCount"] = len(nodes)

    # Build node maps
    node_by_name = {}
    name_dupes = set()
    if isinstance(nodes, list):
        for i, n in enumerate(nodes):
            if not isinstance(n, dict):
                report["errors"].append({
                    "code": "WORKFLOW_INVALID_NODE",
                    "message": "Each entry in `nodes` must be an object.",
                    "path": f"nodes[{i}]",
                })
                continue
            nm = n.get("name")
            if not isinstance(nm, str) or not nm.strip():
                report["errors"].append({
                    "code": "WORKFLOW_INVALID_NODE",
                    "message": "Node must have non-empty string `name`.",
                    "path": f"nodes[{i}].name",
                })
                continue
            if nm in node_by_name:
                name_dupes.add(nm)
            node_by_name[nm] = n

        for nm in sorted(name_dupes):
            report["errors"].append({
                "code": "WORKFLOW_DUPLICATE_NODE_NAME",
                "message": f"Duplicate node name: {nm}",
                "path": "nodes",
            })

    # Node validation (lightweight; no persistence)
    all_registry_nodes = _load("nodes.json")
    registry_by_type = {r.get("node_type"): r for r in all_registry_nodes if isinstance(r, dict)}
    active_registry_types = {k for k, r in registry_by_type.items() if r.get("status") == "active"}

    def _required_paths_for_node(reg_row):
        # Prefer essentials_json.required_user_inputs style if present; else attempt schema_json required list for top-level parameters
        essentials = reg_row.get("essentials_json") if isinstance(reg_row, dict) else None
        if isinstance(essentials, dict):
            req = essentials.get("required_user_inputs")
            if isinstance(req, list):
                out = []
                for it in req:
                    if isinstance(it, dict) and isinstance(it.get("path"), str) and it["path"]:
                        out.append(it["path"])
                if out:
                    return out
        schema = reg_row.get("schema_json") if isinstance(reg_row, dict) else None
        if isinstance(schema, dict):
            # Try common shape: schema.properties + schema.required
            required = schema.get("required")
            if isinstance(required, list):
                # assume these map into node.parameters.<field> or node.parameters[field]
                return [f"parameters.{r}" for r in required if isinstance(r, str)]
        return []

    def _get_path(obj, dotted):
        cur = obj
        for part in dotted.split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur[part]
            else:
                return (False, None)
        return (True, cur)

    if validateNodes and isinstance(nodes, list):
        for idx, n in enumerate(nodes):
            if not isinstance(n, dict):
                continue
            ntype = n.get("type")
            if not isinstance(ntype, str) or not ntype:
                report["errors"].append({
                    "code": "NODE_INVALID",
                    "message": "Node must include string `type`.",
                    "path": f"nodes[{idx}].type",
                })
                continue

            if ntype not in active_registry_types:
                # Unknown or inactive node type
                report["errors"].append({
                    "code": "NODE_TYPE_UNKNOWN_OR_INACTIVE",
                    "message": f"Node type `{ntype}` not found or not active in registry.",
                    "path": f"nodes[{idx}].type",
                })
                continue

            reg = registry_by_type.get(ntype)
            required_paths = _required_paths_for_node(reg)

            # minimal/routine checks required fields only for minimal, else also check simple types
            for rp in required_paths:
                ok, val = _get_path(n, rp)
                if not ok or val is None or (isinstance(val, str) and not val.strip()):
                    report["errors"].append({
                        "code": "NODE_MISSING_REQUIRED",
                        "message": f"Missing required field `{rp}` for node type `{ntype}`.",
                        "path": f"nodes[{idx}].{rp}",
                        "nodeType": ntype,
                        "nodeName": n.get("name"),
                    })

            if profile in ("runtime", "ai-friendly", "strict"):
                # Basic sanity checks for parameters object when present
                if "parameters" in n and not isinstance(n.get("parameters"), dict):
                    report["errors"].append({
                        "code": "NODE_INVALID",
                        "message": "`parameters` must be an object when present.",
                        "path": f"nodes[{idx}].parameters",
                        "nodeType": ntype,
                        "nodeName": n.get("name"),
                    })

            if profile in ("ai-friendly", "strict"):
                # Best-practice hint: description/helpful notes
                if not isinstance(n.get("notes"), str) or not n.get("notes", "").strip():
                    report["suggestions"].append({
                        "code": "NODE_BEST_PRACTICE",
                        "message": "Consider adding `notes` to describe the purpose of this node for maintainability.",
                        "path": f"nodes[{idx}].notes",
                        "nodeName": n.get("name"),
                    })

    # Connections validation
    if validateConnections and isinstance(connections, dict) and isinstance(node_by_name, dict):
        # n8n connections shape: { "NodeName": { "main": [ [ {node, type, index}, ... ] ] } }
        for from_name, from_ports in connections.items():
            if from_name not in node_by_name:
                report["errors"].append({
                    "code": "CONNECTION_INVALID",
                    "message": f"Connection references missing source node `{from_name}`.",
                    "path": f"connections.{from_name}",
                })
                continue
            if not isinstance(from_ports, dict):
                report["errors"].append({
                    "code": "CONNECTION_INVALID",
                    "message": "Connection entry must be an object with connection types (e.g., main, ai_tool).",
                    "path": f"connections.{from_name}",
                })
                continue
            for port_type, lanes in from_ports.items():
                if not isinstance(lanes, list):
                    report["errors"].append({
                        "code": "CONNECTION_INVALID",
                        "message": f"Connection lanes for `{port_type}` must be an array.",
                        "path": f"connections.{from_name}.{port_type}",
                    })
                    continue
                for li, lane in enumerate(lanes):
                    if lane is None:
                        continue
                    if not isinstance(lane, list):
                        report["errors"].append({
                            "code": "CONNECTION_INVALID",
                            "message": "Each lane must be an array of connection objects.",
                            "path": f"connections.{from_name}.{port_type}[{li}]",
                        })
                        continue
                    for ci, conn in enumerate(lane):
                        if not isinstance(conn, dict):
                            report["errors"].append({
                                "code": "CONNECTION_INVALID",
                                "message": "Each connection must be an object with at least `node`.",
                                "path": f"connections.{from_name}.{port_type}[{li}][{ci}]",
                            })
                            continue
                        to_node = conn.get("node")
                        if not isinstance(to_node, str) or not to_node:
                            report["errors"].append({
                                "code": "CONNECTION_INVALID",
                                "message": "Connection must specify target `node` as string.",
                                "path": f"connections.{from_name}.{port_type}[{li}][{ci}].node",
                            })
                            continue
                        if to_node not in node_by_name:
                            report["errors"].append({
                                "code": "CONNECTION_TARGET_MISSING",
                                "message": f"Connection from `{from_name}` references missing target node `{to_node}`.",
                                "path": f"connections.{from_name}.{port_type}[{li}][{ci}].node",
                            })
                        # ai_tool connections best-practice: target should be usable_as_tool node if connecting via ai_tool
                        if port_type == "ai_tool" and to_node in node_by_name:
                            tgt_type = node_by_name[to_node].get("type")
                            reg = registry_by_type.get(tgt_type)
                            if reg and reg.get("status") == "active" and reg.get("usable_as_tool") is False:
                                report["warnings"].append({
                                    "code": "AI_TOOL_CONNECTION_NON_TOOL_NODE",
                                    "message": f"ai_tool connection targets `{to_node}` of type `{tgt_type}`, which is not marked usable_as_tool.",
                                    "path": f"connections.{from_name}.{port_type}[{li}][{ci}]",
                                })

    # Expression validation (lightweight)
    if validateExpressions and isinstance(workflow, dict) and isinstance(nodes, list):
        # Scan for n8n-style expressions in all string values: {{ ... }}
        expr_pat = re.compile(r"\{\{([\s\S]*?)\}\}")
        from_ai_pat = re.compile(r"\$fromAI\(", re.IGNORECASE)

        missing_node_refs = 0
        expr_issues = 0

        def _walk(obj, path=""):
            nonlocal missing_node_refs, expr_issues
            if isinstance(obj, dict):
                for k, v in obj.items():
                    _walk(v, f"{path}.{k}" if path else str(k))
            elif isinstance(obj, list):
                for i, v in enumerate(obj):
                    _walk(v, f"{path}[{i}]")
            elif isinstance(obj, str):
                for m in expr_pat.finditer(obj):
                    expr = m.group(1)
                    # Basic braces balance / emptiness check
                    if not expr.strip():
                        expr_issues += 1
                        report["errors"].append({
                            "code": "EXPRESSION_INVALID",
                            "message": "Empty expression `{{}}` is not valid.",
                            "path": path,
                        })
                    # Look for $node["Name"] references and validate node exists
                    for nm in re.findall(r"""\$node\[\s*["']([^"']+)["']\s*\]""", expr):
                        if nm not in node_by_name:
                            missing_node_refs += 1
                            report["errors"].append({
                                "code": "EXPRESSION_NODE_REFERENCE_MISSING",
                                "message": f"Expression references missing node `{nm}`.",
                                "path": path,
                            })
                    # $fromAI() hints
                    if from_ai_pat.search(expr):
                        # Ensure it's not in a context that seems obviously wrong; keep as warning
                        report["suggestions"].append({
                            "code": "EXPRESSION_FROM_AI_PRESENT",
                            "message": "Detected $fromAI() usage; ensure the workflow is executed in a context where AI inputs are provided.",
                            "path": path,
                        })

        _walk(workflow, "")

        report["summary"]["expressionProblems"] = missing_node_refs + expr_issues

    report["summary"]["errorCount"] = len(report["errors"])
    report["summary"]["warningCount"] = len(report["warnings"])
    report["summary"]["suggestionCount"] = len(report["suggestions"])
    report["summary"]["connectionProblems"] = report["summary"]["connectionProblems"]  # placeholder, kept for compatibility
    report["ok"] = report["summary"]["errorCount"] == 0

    # Log and return
    if report["ok"]:
        _log("ok", params, {"ok": True, "errorCount": report["summary"]["errorCount"], "warningCount": report["summary"]["warningCount"]}, None)
    else:
        _log("error", params, {"ok": False, "errorCount": report["summary"]["errorCount"]}, "VALIDATION_ERROR")
    return report

def validate_workflow_connections(workflow, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    tool_name = "validate_workflow_connections"
    params = {"workflow": workflow}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "enn_req_" + uuid.uuid4().hex[:26]

    def _log(status, duration_ms, error_code=None, response_summary=None):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        ts = _now_iso()
        reqs.append({
            "id": _new_req_id(),
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "response_summary": response_summary,
            "status": status,
            "error_code": error_code,
            "duration_ms": int(max(0, duration_ms)),
            "created_at": ts,
            "updated_at": ts,
        })
        _save("api_requests.json", reqs)

    def _finish_ok(body, summary=None):
        _log("ok", (time.time() - _t0) * 1000, response_summary=summary)
        return body

    def _finish_err(code, msg, error_code, **x):
        _log("error", (time.time() - _t0) * 1000, error_code=error_code, response_summary={"error_code": error_code})
        return _err(code, msg, error_code=error_code, **x)

    # Relaxed structure validation: {} should be accepted as valid-under-schema input (it's an object)
    if not isinstance(workflow, dict):
        return _finish_err("VALIDATION_ERROR", "Business rule: workflow must be an object.", "VALIDATION_FAILED")

    nodes = workflow.get("nodes", [])
    connections = workflow.get("connections", {})

    # For this tool, missing nodes/connections is treated as an empty workflow (valid)
    if nodes is None:
        nodes = []
    if connections is None:
        connections = {}

    if not isinstance(nodes, list):
        return _finish_err("VALIDATION_ERROR", "Business rule: workflow.nodes must be an array when provided.", "VALIDATION_FAILED")
    if not isinstance(connections, dict):
        return _finish_err("VALIDATION_ERROR", "Business rule: workflow.connections must be an object when provided.", "VALIDATION_FAILED")

    # Basic connectivity checks
    node_names = []
    node_by_name = {}
    errors = []
    warnings = []

    for idx, n in enumerate(nodes):
        if not isinstance(n, dict):
            errors.append({"code": "INVALID_NODE", "message": "Node must be an object.", "index": idx})
            continue
        name = n.get("name")
        if not isinstance(name, str) or not name.strip():
            errors.append({"code": "INVALID_NODE_NAME", "message": "Node.name must be a non-empty string.", "index": idx})
            continue
        if name in node_by_name:
            errors.append({"code": "DUPLICATE_NODE_NAME", "message": "Duplicate node name.", "name": name})
            continue
        node_names.append(name)
        node_by_name[name] = n

    # Parse connections to edges: n8n-like shape {NodeName: {main: [[{node, type, index}, ...]], ...}}
    edges = []
    if connections:
        for src, out in connections.items():
            if not isinstance(src, str):
                continue
            if not isinstance(out, dict):
                errors.append({"code": "INVALID_CONNECTIONS", "message": "connections entries must be objects.", "node": src})
                continue
            for port, groups in out.items():
                if not isinstance(groups, list):
                    continue
                for gi, group in enumerate(groups):
                    if not isinstance(group, list):
                        continue
                    for ti, target in enumerate(group):
                        if not isinstance(target, dict):
                            continue
                        dst = target.get("node")
                        if isinstance(dst, str):
                            edges.append((src, dst, port, gi, ti))

    # references must exist
    for (src, dst, port, gi, ti) in edges:
        if src not in node_by_name:
            errors.append({"code": "CONNECTION_UNKNOWN_SOURCE", "message": "Connection source node does not exist in workflow.nodes.", "source": src})
        if dst not in node_by_name:
            errors.append({"code": "CONNECTION_UNKNOWN_TARGET", "message": "Connection target node does not exist in workflow.nodes.", "source": src, "target": dst})

    # cycle detection (simple DFS on known nodes)
    graph = {n: [] for n in node_by_name.keys()}
    for (src, dst, *_rest) in edges:
        if src in graph and dst in graph:
            graph[src].append(dst)

    visited = set()
    stack = set()
    cycles = []

    def _dfs(u, path):
        visited.add(u)
        stack.add(u)
        for v in graph.get(u, []):
            if v not in visited:
                _dfs(v, path + [v])
            elif v in stack:
                cycles.append(path + [v])
        stack.discard(u)

    for n in list(graph.keys()):
        if n not in visited:
            _dfs(n, [n])

    if cycles:
        errors.append({"code": "CYCLE_DETECTED", "message": "Workflow graph contains a cycle.", "cycles": cycles[:10]})

    # orphan nodes: nodes with no in/out edges (informational warning)
    if node_by_name:
        indeg = {n: 0 for n in node_by_name}
        outdeg = {n: 0 for n in node_by_name}
        for (src, dst, *_rest) in edges:
            if src in outdeg:
                outdeg[src] += 1
            if dst in indeg:
                indeg[dst] += 1
        orphans = [n for n in node_by_name if indeg[n] == 0 and outdeg[n] == 0]
        if orphans:
            warnings.append({"code": "ORPHAN_NODES", "message": "Some nodes are not connected.", "nodes": orphans})

    body = {
        "ok": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
        "stats": {"nodeCount": len(node_by_name), "edgeCount": len(edges)},
    }
    return _finish_ok(body, summary={"ok": body["ok"], "errors": len(errors), "warnings": len(warnings)})

