    def _finish_err(code, msg, error_code, **x):
        _log("error", (time.time() - _t0) * 1000, error_code=error_code, response_summary={"error_code": error_code})
        return _err(code, msg, error_code=error_code, **x)

    # Relaxed: {} accepted as empty workflow
    if not isinstance(workflow, dict):
        return _finish_err("VALIDATION_ERROR", "Business rule: workflow must be an object.", "VALIDATION_FAILED")

    nodes = workflow.get("nodes", [])
    if nodes is None:
        nodes = []
    if not isinstance(nodes, list):
        return _finish_err("VALIDATION_ERROR", "Business rule: workflow.nodes must be an array when provided.", "VALIDATION_FAILED")

    node_names = set()
    for n in nodes:
        if isinstance(n, dict) and isinstance(n.get("name"), str):
            node_names.add(n["name"])

    # Expression patterns: {{ ... }}
    expr_re = re.compile(r"\{\{([\s\S]*?)\}\}")
    node_ref_re = re.compile(r"\$node\[['\"]([^'\"]+)['\"]\]")

    errors = []
    warnings = []

    def _walk(obj, path):
        if isinstance(obj, dict):
            for k, v in obj.items():
                _walk(v, path + [k])
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                _walk(v, path + [i])
        elif isinstance(obj, str):
            for m in expr_re.finditer(obj):
                expr = m.group(0)
                inner = m.group(1)

                # basic syntax sanity: must not be empty
                if inner.strip() == "":
                    errors.append({"code": "EMPTY_EXPRESSION", "message": "Expression is empty.", "path": path, "expression": expr})
                    continue

                # check node references exist
                for nm in node_ref_re.finditer(inner):
                    ref = nm.group(1)
                    if ref not in node_names:
                        errors.append({
                            "code": "UNKNOWN_NODE_REFERENCE",
                            "message": "Expression references a node name that does not exist in workflow.nodes.",
                            "path": path,
                            "node": ref,
                            "expression": expr,
                        })

                # quick brace check (avoid false positives but catch obvious issues)
                if "{{" in inner or "}}" in inner:
                    warnings.append({"code": "NESTED_BRACES", "message": "Expression contains nested '{{' or '}}' which may be invalid.", "path": path, "expression": expr})

    _walk(workflow, [])

    body = {
        "ok": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
        "stats": {"nodeCount": len(node_names), "expressionsChecked": len(errors) + len(warnings)},
    }
    return _finish_ok(body, summary={"ok": body["ok"], "errors": len(errors), "warnings": len(warnings)})

