    def _finish_err(code, msg, error_code, **x):
        _log("error", (time.time() - _t0) * 1000, response_summary={"error_code": error_code}, error_code=error_code)
        return _err(code, msg, error_code=error_code, **x)

    # Auth is ambient; no explicit credentials exist in schema. Always proceed.

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "disabled"):
            return _finish_err("VALIDATION_ERROR", "`status` must be one of: active, deprecated, disabled.", "VALIDATION_FAILED")
    if packageNamePrefix is not None and not isinstance(packageNamePrefix, str):
        return _finish_err("VALIDATION_ERROR", "`packageNamePrefix` must be a string.", "VALIDATION_FAILED")
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _finish_err("VALIDATION_ERROR", "`limit` must be a number between 1 and 200.", "BAD_LIMIT")
        if int(limit) != limit:
            return _finish_err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 200.", "BAD_LIMIT")
        limit_v = int(limit)
    if limit_v < 1 or limit_v > 200:
        return _finish_err("VALIDATION_ERROR", "`limit` must be between 1 and 200.", "BAD_LIMIT")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _finish_err("VALIDATION_ERROR", "`cursor` must be a non-empty string when provided.", "VALIDATION_FAILED")
        # cursor is base64url of "offset:<int>"
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return _finish_err("VALIDATION_ERROR", "Invalid cursor.", "VALIDATION_FAILED")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _finish_err("VALIDATION_ERROR", "Invalid cursor offset.", "VALIDATION_FAILED")
        except Exception:
            return _finish_err("VALIDATION_ERROR", "Invalid cursor.", "VALIDATION_FAILED")

    pkgs = _load("node_packages.json")
    if not isinstance(pkgs, list):
        pkgs = []

    # Filter
    out = []
    pref = packageNamePrefix.lower() if isinstance(packageNamePrefix, str) else None
    for p in pkgs:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        if pref is not None:
            pn = p.get("package_name")
            if not isinstance(pn, str) or not pn.lower().startswith(pref):
                continue
        out.append(p)

    # Sort stable by package_name then id for deterministic pagination
    def _k(p):
        pn = p.get("package_name")
        return ((pn or "").lower(), p.get("id") or "")
    out.sort(key=_k)

    total = len(out)
    page = out[start:start + limit_v]
    next_cursor = None
    has_more = start + limit_v < total
    if has_more:
        nxt = f"offset:{start + limit_v}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    body = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    return _finish_ok(body, summary={"returned": len(page), "total": total, "has_more": has_more})

