def update_node_package_status(id, status, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0396000" if __import__("os").path.isdir("./environment_mix/0396000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(tool_name, request_params, status_str, duration_ms, error_code=None, response_summary=None):
        api_requests = _load("api_requests.json")
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "status": status_str,
            "error_code": error_code,
            "duration_ms": int(duration_ms),
            "created_at": now,
            "updated_at": now,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    def _rate_limit_ok(tool_name):
        # Simple per-tool sliding window based on api_requests logs.
        # Since no explicit quotas are provided in schema, enforce a conservative limit.
        api_requests = _load("api_requests.json")
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 120  # per tool per minute
        cutoff = now - datetime.timedelta(seconds=window_s)

        def _parse(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        recent = 0
        for r in api_requests:
            if r.get("tool_name") != tool_name:
                continue
            t = _parse(r.get("created_at"))
            if t and t >= cutoff:
                recent += 1
                if recent >= limit_per_window:
                    return False
        return True

    tool_name = "update_node_package_status"
    request_params = {"id": id, "status": status}

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="VALIDATION_ERROR",
                     response_summary={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    allowed_status = {"active", "deprecated", "disabled"}
    if not isinstance(status, str) or status not in allowed_status:
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="VALIDATION_ERROR",
                     response_summary={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled", field="status",
                    allowed=list(sorted(allowed_status)))

    # Ambient auth: allow if datastore exists; refuse only if datastore is unusable for serving calls.
    # We consider presence of required collections as sufficient for authorization.
    # If database path is missing entirely, treat as unauthorized (no serving context).
    if not os.path.isdir(_DB):
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="UNAUTHORIZED",
                     response_summary={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No serving context available")

    # Rate limit
    if not _rate_limit_ok(tool_name):
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="RATE_LIMIT",
                     response_summary={"error": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    node_packages = _load("node_packages.json")
    pkg = None
    idx = None
    for i, r in enumerate(node_packages):
        if r.get("id") == id:
            pkg = r
            idx = i
            break

    if not pkg:
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="NOT_FOUND",
                     response_summary={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "node package not found", id=id)

    current = pkg.get("status")
    transitions = {
        "active": {"deprecated", "disabled"},
        "deprecated": {"disabled"},
        "disabled": set(),
    }
    if current not in transitions:
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="INVALID_TRANSITION",
                     response_summary={"error": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "package is in an unknown lifecycle state", current_status=current)

    if status == current:
        # Idempotent: no state change, but request still succeeds with current record.
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "ok", dur, error_code=None,
                     response_summary={"updated": False, "id": id, "status": current})
        return {"package": pkg, "updated": False}

    if status not in transitions[current]:
        dur = (time.time() - start) * 1000
        _log_request(tool_name, request_params, "error", dur, error_code="VALIDATION_ERROR",
                     response_summary={"error": "VALIDATION_ERROR"})
        return _err(
            "VALIDATION_ERROR",
            "invalid status transition",
            current_status=current,
            requested_status=status,
            allowed_transitions=sorted(list(transitions[current])),
        )

    # Apply mutation
    now = _now_iso()
    updated = dict(pkg)
    updated["status"] = status
    updated["updated_at"] = now
    node_packages[idx] = updated
    _save("node_packages.json", node_packages)

    dur = (time.time() - start) * 1000
    _log_request(tool_name, request_params, "ok", dur, error_code=None,
                 response_summary={"updated": True, "id": id, "from": current, "to": status})
    return {"package": updated, "updated": True}

