        filt.append(r)

    # stable order by updated_at desc then id
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _sort_key(r):
        dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (-dt.timestamp(), r.get("id") or "")

    filt.sort(key=_sort_key)

    total = len(filt)
    page = filt[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "taskKey": r.get("task_key"),
            "category": r.get("category"),
            "title": r.get("title"),
            "description": r.get("description"),
            "recommendedNodeType": r.get("recommended_node_type"),
            "requiredUserInputs": r.get("required_user_inputs"),
            "preconfiguredConfig": r.get("preconfigured_config"),
            "status": r.get("status"),
            "createdAt": r.get("created_at"),
            "updatedAt": r.get("updated_at"),
        })

    body = {
        "data": out,
        "pagination": {
            "total": total,
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }
    return _finish_ok(body, summary={"returned": len(out), "total": total, "has_more": has_more})
